definitions.query:
SELECT r.vehicle_class, r.day_type, r.peak_required, r.reserve_required
FROM `ops`.`service_requirement` r
WHERE r.timetable_version = 'HIV-2026';

SELECT a.project_code, COUNTIF(a.result = 'Passed') / COUNT(*) AS completeness
FROM `ppm`.`acceptance_item` a
GROUP BY a.project_code;

SELECT l.project_code, SUM(l.ordered_eur - l.received_eur - l.cancelled_eur) AS open_commitment_eur
FROM `proc`.`po_line` l
GROUP BY 1;
